from treelib import Tree

from ..robot_compatibility import get_keywords
from ..utils.encoder import shorten_text


class KeywordsVisitor:

    def __init__(self, parser):
        """
        :param parser:  Parser which is able to read keyword properties and generate generic structure.
        """
        self._parser = parser
        self._node_id = 1

    def build(self, keywords, shorten=True) -> list:
        """Build data structure to report requested values.

        :param keywords: Iterable structure which contains keywords.
        :param shorten: Determines if keyword`s texts should be trimmed to maximum 120 characters

        :return: Data structure which represents matches for given parser.
        :rtype: list
        """
        results = []
        for keyword in keywords:
            result = self._parser.parse(keyword)
            if result:
                if shorten:
                    result = shorten_text(result)
                results += [result]
            kws = get_keywords(keyword)
            if kws:
                results += self.build(kws, shorten)
        return results

    def build_fail_log_path(self, keywords):
        """Build data structure to report PM counters.

        :param keywords: Iterable structure which contains keywords.

        :return: Tree data structure which represents fail_log_path for step.
        :rtype: Tree
        """
        fail_tree = Tree()
        fail_tree.create_node("root", self._node_id)
        fail_tree = self._populate_fail_tree(fail_tree, keywords, fail_tree.root)
        return self._build_paths_without_root(fail_tree)

    def _populate_fail_tree(self, fail_tree, keywords, parent):
        for keyword in keywords:
            result = self._parser.parse(keyword)
            if result:
                self._node_id += 1
                result = shorten_text(result)
                fail_tree.create_node(result, self._node_id, parent=parent)
                kws = get_keywords(keyword)
                if kws:
                    fail_tree = self._populate_fail_tree(fail_tree, kws, self._node_id)
        return fail_tree

    def _build_paths_without_root(self, tree):
        fail_path_list = []
        for path in tree.paths_to_leaves():
            path.remove(tree.root)
            fail_path_list.append([tree.get_node(each).tag for each in path])
        return fail_path_list
